package kw.urtv.home;
import android.content.*;import android.content.pm.*;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.widget.TextView;import java.net.*;import java.io.*;import java.security.*;import java.util.*;import java.util.concurrent.*;import org.json.*;import kw.urtv.shared.TvPage;
/** User-initiated only. HTTPS + digest + package + signer + version checked before Android consent. */
public class UpdateActivity extends TvPage {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private volatile HttpURLConnection connection;private volatile boolean dead,cancelled;private boolean busy;private JSONObject release;private TextView status;private boolean previews=true;
 @Override public void onCreate(Bundle b){super.onCreate(b);render();}
 private void render(){title("تحديث KLightTV","فحص وتنزيل عند طلبك فقط");note("الرئيسية: "+version("kw.urtv.home")+"     شاشة التوقف: "+version("kw.urtv.screensaver"));
 addButton(previews?"القناة: الإصدارات التجريبية والمستقرة":"القناة: الإصدارات المستقرة فقط",()->{if(busy)return;previews=!previews;release=null;render();});
 addButton("البحث عن تحديث",this::check);status=text("لم يُجرَ فحص بعد.",17,0xFFB9CADA);list.addView(status);
 if(release!=null){note(release.optString("name"));String body=release.optString("body");note(body.length()>900?body.substring(0,900):body);
 for(String pkg:new String[]{"kw.urtv.home","kw.urtv.screensaver"}){String label=pkg.endsWith("home")?"الرئيسية":"شاشة التوقف";if(newer(release.optString("tag_name"),version(pkg)))addButton("تنزيل وتثبيت تحديث "+label,()->download(pkg));else note(label+": النسخة المثبتة مساوية للإصدار المنشور أو أحدث منه.");}}
 if(!getPackageManager().canRequestPackageInstalls())addButton("السماح بتثبيت التحديثات",()->{try{startActivity(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+getPackageName())));}catch(Exception e){status.setText("افتح إعدادات التلفزيون ← تثبيت تطبيقات غير معروفة ← KLightTV.");}});
 addButton("رجوع",this::finish);
 }
 static boolean newer(String tag,String installed){try{String[] a=tag.replaceFirst("^v","").split("\\."),b=installed.split("\\.");if(a.length!=3||b.length!=3)return true;for(int i=0;i<3;i++){int x=Integer.parseInt(a[i]),y=Integer.parseInt(b[i]);if(x!=y)return x>y;}return false;}catch(Exception e){return true;}}
 private String version(String pkg){try{return getPackageManager().getPackageInfo(pkg,0).versionName;}catch(Exception e){return "غير مثبت";}}
 private void post(Runnable r){runOnUiThread(()->{if(!dead&&!isFinishing())r.run();});}
 private void check(){if(busy)return;busy=true;cancelled=false;status.setText("جارٍ الاتصال بـ GitHub…");final boolean channel=previews;worker.execute(()->{try{JSONArray all=new JSONArray(new String(bytes("https://api.github.com/repos/linkq8/KLightTV/releases?per_page=30",1048576),"UTF-8"));JSONObject found=null;
 for(int i=0;i<all.length();i++){JSONObject v=all.getJSONObject(i);if(v.optBoolean("draft")||(!channel&&v.optBoolean("prerelease")))continue;if(!v.optString("tag_name").matches("v[0-9]+\\.[0-9]+\\.[0-9]+"))continue;found=v;break;}
 final JSONObject result=found;post(()->{busy=false;release=result;render();status.setText(result==null?"لا توجد إصدارات في هذه القناة.":"اكتمل الفحص. التثبيت يتطلب موافقتك في Android.");});
 }catch(Exception e){post(()->{busy=false;status.setText("تعذر فحص التحديثات. تحقق من الإنترنت وأعد المحاولة.");});}});}
 private void download(String pkg){if(busy||release==null)return;if(!getPackageManager().canRequestPackageInstalls()){status.setText("امنح صلاحية تثبيت التحديثات أولًا، ثم أعد المحاولة.");return;}busy=true;cancelled=false;status.setText("جارٍ التنزيل والتحقق…");final JSONObject selected=release;
 worker.execute(()->{File file=new File(getCacheDir(),"verified.apk");try{JSONObject asset=null;String wanted=pkg.endsWith("home")?"KLightTV-home-android-tv.apk":"KLightTV-screensaver-android-tv.apk";JSONArray items=selected.getJSONArray("assets");for(int i=0;i<items.length();i++)if(wanted.equals(items.getJSONObject(i).optString("name")))asset=items.getJSONObject(i);if(asset==null)throw new IOException("missing");
 String url=asset.getString("browser_download_url"),digest=asset.optString("digest");if(!url.startsWith("https://github.com/linkq8/KLightTV/releases/download/")||!digest.matches("sha256:[a-f0-9]{64}"))throw new IOException("unverified release");
 HttpURLConnection c=open(url);MessageDigest sha=MessageDigest.getInstance("SHA-256");long count=0;try(InputStream in=c.getInputStream();OutputStream out=new FileOutputStream(file)){byte[] buf=new byte[32768];int n;while((n=in.read(buf))!=-1){if(dead||cancelled||Thread.currentThread().isInterrupted())throw new InterruptedIOException();count+=n;if(count>52428800)throw new IOException("limit");sha.update(buf,0,n);out.write(buf,0,n);}}finally{c.disconnect();connection=null;}
 if(count!=asset.getLong("size")||!digest.substring(7).equals(hex(sha.digest())))throw new IOException("digest");
 PackageManager pm=getPackageManager();PackageInfo apk=pm.getPackageArchiveInfo(file.getAbsolutePath(),PackageManager.GET_SIGNATURES);PackageInfo current;boolean installed=true;try{current=pm.getPackageInfo(pkg,PackageManager.GET_SIGNATURES);}catch(PackageManager.NameNotFoundException missing){current=pm.getPackageInfo(getPackageName(),PackageManager.GET_SIGNATURES);installed=false;}
 if(apk==null||!pkg.equals(apk.packageName)||!selected.getString("tag_name").equals("v"+apk.versionName)||(installed&&apk.versionCode<=current.versionCode)||!Arrays.equals(apk.signatures,current.signatures))throw new IOException("version or signer");
 if(cancelled)throw new InterruptedIOException();post(()->{busy=false;if(cancelled){status.setText("أُلغي التنزيل عند مغادرة الصفحة.");return;}status.setText("تم التحقق من الملف. أكمل التأكيد في شاشة Android.");Uri uri=Uri.parse("content://kw.urtv.home.updates/verified.apk");try{Intent install=new Intent(Intent.ACTION_INSTALL_PACKAGE).setDataAndType(uri,"application/vnd.android.package-archive").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(install);}catch(Exception e){status.setText("لا تتوفر واجهة تثبيت على هذا الجهاز. استخدم أداة الكمبيوتر.");}});
 }catch(Exception e){file.delete();post(()->{busy=false;status.setText("لم يُثبّت شيء: قد تكون النسخة الحالية أحدث، أو تعذر التنزيل والتحقق. يمكنك إعادة المحاولة.");});}});
 }
 private static String hex(byte[] bytes){StringBuilder b=new StringBuilder();for(byte x:bytes)b.append(String.format(Locale.ROOT,"%02x",x&255));return b.toString();}
 private HttpURLConnection open(String address)throws Exception{URL url=new URL(address);for(int n=0;n<6;n++){if(dead||cancelled)throw new InterruptedIOException();String host=url.getHost();if(!"https".equals(url.getProtocol())||!(host.equals("github.com")||host.equals("api.github.com")||host.equals("release-assets.githubusercontent.com")||host.equals("objects.githubusercontent.com")))throw new IOException("host");HttpURLConnection c=(HttpURLConnection)url.openConnection();connection=c;c.setConnectTimeout(10000);c.setReadTimeout(15000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","KLightTV-Android");int code=c.getResponseCode();if(code>=300&&code<400){String loc=c.getHeaderField("Location");c.disconnect();url=new URL(url,loc);continue;}if(code!=200){c.disconnect();throw new IOException("http");}return c;}throw new IOException("redirect");}
 private byte[] bytes(String u,int max)throws Exception{HttpURLConnection c=open(u);try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(dead||cancelled||out.size()+n>max)throw new IOException();out.write(b,0,n);}return out.toByteArray();}finally{c.disconnect();connection=null;}}
 @Override public void onStop(){super.onStop();if(busy){cancelled=true;HttpURLConnection c=connection;if(c!=null)c.disconnect();}}
 @Override public void onDestroy(){dead=true;worker.shutdownNow();HttpURLConnection c=connection;if(c!=null)c.disconnect();super.onDestroy();}
}
